export default function BlockRenderer({
  block
}) {
  if (!block) {
    return null;
  }

  switch (block.type) {
    case "html":
      return (
        <HtmlBlock
          data={block.data}
        />
      );

    case "chart":
      return (
        <ChartRenderer
          data={block.data || {}}
        />
      );

    case "simulation":
      return (
        <SimulationRenderer
          data={block.data || {}}
        />
      );

    case "next_route":
      return (
        <RouteRenderer
          data={(block.data)}
        />
      );

    default:
      return (
        <JsonBlock
          title={
            `Unsupported block: ${
              block.type ||
              "unknown"
            }`
          }
          data={block}
        />
      );
  }
}


