            )
        )

        score_key = (
            score
            .lower()
            .replace(" ", "_")
        )

        colour = {
            "very_high": "confidence-high",
            "high": "confidence-high",
            "medium": "confidence-medium",
            "low": "confidence-low",
            "very_low": "confidence-low",
        }.get(
            score_key,
            "confidence-medium",
        )

        claim = html.escape(
            assessment.get(
                "claim",
                "",
            )
        )

        rationale = html.escape(
            assessment.get(
                "rationale",
                "",
            )
        )

        assessments_html.append(
            f"""
